{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "17-Methyltestosterone has good oral bioavailability in humans; its 17-modified steroid scaffold resists first-pass metabolism, supporting high oral bioavailability for the query's 17-acetoxy/17-acetyl modification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Cortisone showed 84% absolute oral bioavailability in humans after oral administration, a high-transfer 4-en-3-one steroid result supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Hydrocortisone showed 95.9% absolute oral bioavailability after 20 mg oral vs IV in eight subjects, directly supporting high oral bioavailability for a closely related corticosteroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Norethindrone absolute oral bioavailability was 64% (range 47–73%) in women, a high-transfer 19-nor steroid with the same 4-en-3-one system, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Cyproterone acetate has almost complete absolute oral bioavailability (88% of dose) in humans and shares the 17-acetoxy-17-acetyl motif with the query, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Chlormadinone acetate has approximately 100% oral bioavailability in humans and shares the 17-acetoxy-17-acetyl and 4-en-3-one features, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Nomegestrol acetate has 63.4% absolute oral bioavailability in healthy women and shares the 17-acetoxy-17-acetyl steroid framework, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Progesterone has only about 5% oral bioavailability due to gut and liver metabolism, but this low-F analogue has low transferability because it lacks the 17-acetoxy/17-acetyl and aryl-substituent features of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Medroxyprogesterone acetate has <10% oral bioavailability, but its very low transfer score and structural differences (6-methyl, no 11-aryl substituent) limit its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer steroid analogues with the same 4-en-3-one and 17-acetoxy/17-acetyl features show absolute oral bioavailability of 52–100%, well above the 20% threshold. Low-F analogues such as progesterone and medroxyprogesterone acetate have much lower transferability and lack key structural features of the query. Therefore the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The effect of the 11β-(4-dimethylaminophenyl) substituent on first-pass metabolism and absorption is not directly measured in this 17-acetoxy-17-acetyl series.",
    "High logD and molecular weight may pose solubility/dissolution limitations that are not experimentally assessed.",
    "Potential 17-acetate hydrolysis or prodrug behavior is not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

